import math

def principal(alpha, gamma, r, r1, r2, P1, P2, p, p1, p2, e2):
    return [[8*alpha*gamma*p1*r1*math.exp(-gamma*p)/r**2 + 2/r, 0, 4*alpha*gamma*(r1**2 - 1)*math.exp(-gamma*p)/r**2], [4*P1*alpha*gamma*p1*math.exp(-gamma*p)/r + 1/r, 4*alpha*gamma*p1*r1*math.exp(-gamma*p)/r + 1, 4*P1*alpha*gamma*r1*math.exp(-gamma*p)/r], [-16*P1*alpha*gamma*r1*math.exp(-gamma*p)/r**2, 8*alpha*gamma*(1 - r1**2)*math.exp(-gamma*p)/r**2, 1]]

def resto(alpha, gamma, w, r, r1, r2, P1, P2, p, p1, p2, e2, a0, a1, d0, d1, q0, q1):
    return [8*alpha*d0*gamma**2*p1**2*r1**2*math.exp(-gamma*p)/r**3 - 8*alpha*d0*gamma**2*p1**2*math.exp(-gamma*p)/r**3 - 16*alpha*d0*gamma*p1*r1*r2*math.exp(-gamma*p)/r**3 - 8*alpha*d0*gamma*p2*r1**2*math.exp(-gamma*p)/r**3 + 8*alpha*d0*gamma*p2*math.exp(-gamma*p)/r**3 - 8*alpha*d1*gamma**2*p1**2*r1*math.exp(-gamma*p)/r**2 + 8*alpha*d1*gamma*p1*r2*math.exp(-gamma*p)/r**2 + 8*alpha*d1*gamma*p2*r1*math.exp(-gamma*p)/r**2 + 4*alpha*gamma**3*p1**2*q0*r1**2*math.exp(-gamma*p)/r**2 - 4*alpha*gamma**3*p1**2*q0*math.exp(-gamma*p)/r**2 - 8*alpha*gamma**2*p1*q0*r1*r2*math.exp(-gamma*p)/r**2 - 8*alpha*gamma**2*p1*q1*r1**2*math.exp(-gamma*p)/r**2 + 8*alpha*gamma**2*p1*q1*math.exp(-gamma*p)/r**2 - 4*alpha*gamma**2*p2*q0*r1**2*math.exp(-gamma*p)/r**2 + 4*alpha*gamma**2*p2*q0*math.exp(-gamma*p)/r**2 + 8*alpha*gamma*q1*r1*r2*math.exp(-gamma*p)/r**2 - 2*d0*r2/r**2 - 2*d0*r1**2/r**3 + 2*d0/r**3 + 2*d1*r1/r**2 + (1/2)*p1*q1, -4*P1**2*alpha*d0*gamma*p1*r1*math.exp(-gamma*p)/r**2 + 4*P1**2*alpha*d1*gamma*p1*math.exp(-gamma*p)/r - 4*P1**2*alpha*gamma**2*p1*q0*r1*math.exp(-gamma*p)/r + 4*P1**2*alpha*gamma*q1*r1*math.exp(-gamma*p)/r + 8*P1*a1*alpha*gamma*p1*r1*math.exp(-gamma*p)/r + 2*P1*a1 + 4*P1*alpha*d0*gamma**2*p1**2*r1*math.exp(-gamma*p)/r**2 - 4*P1*alpha*d0*gamma*p1*r2*math.exp(-gamma*p)/r**2 - 4*P1*alpha*d0*gamma*p2*r1*math.exp(-gamma*p)/r**2 - 4*P1*alpha*d1*gamma**2*p1**2*math.exp(-gamma*p)/r + 4*P1*alpha*d1*gamma*p2*math.exp(-gamma*p)/r + 4*P1*alpha*gamma**3*p1**2*q0*r1*math.exp(-gamma*p)/r - 4*P1*alpha*gamma**2*p1*q0*r2*math.exp(-gamma*p)/r - 8*P1*alpha*gamma**2*p1*q1*r1*math.exp(-gamma*p)/r - 4*P1*alpha*gamma**2*p2*q0*r1*math.exp(-gamma*p)/r + 4*P1*alpha*gamma*q1*r2*math.exp(-gamma*p)/r - P1*d0*r1/r**2 + P1*d1/r - 4*P2*alpha*d0*gamma*p1*r1*math.exp(-gamma*p)/r**2 + 4*P2*alpha*d1*gamma*p1*math.exp(-gamma*p)/r - 4*P2*alpha*gamma**2*p1*q0*r1*math.exp(-gamma*p)/r + 4*P2*alpha*gamma*q1*r1*math.exp(-gamma*p)/r - 4*a1*alpha*gamma**2*p1**2*r1*math.exp(-gamma*p)/r + 4*a1*alpha*gamma*p1*r2*math.exp(-gamma*p)/r + 4*a1*alpha*gamma*p2*r1*math.exp(-gamma*p)/r + a1*r1/r - 4*alpha*d0*e2*gamma**2*p1**2*w*math.exp(-gamma*p)/r + 4*alpha*d0*e2*gamma*p2*w*math.exp(-gamma*p)/r + 4*alpha*e2*gamma*q0*r2*w*math.exp(-gamma*p)/r + d0*e2*w/r - d0*r2/r**2 + (1/2)*p1*q1, 16*P1**2*alpha*d0*gamma*r1**2*math.exp(-gamma*p)/r**3 - 16*P1**2*alpha*d0*gamma*math.exp(-gamma*p)/r**3 - 16*P1**2*alpha*d1*gamma*r1*math.exp(-gamma*p)/r**2 + 8*P1**2*alpha*gamma**2*q0*r1**2*math.exp(-gamma*p)/r**2 - 8*P1**2*alpha*gamma**2*q0*math.exp(-gamma*p)/r**2 - 16*P1*a1*alpha*gamma*r1**2*math.exp(-gamma*p)/r**2 + 16*P1*a1*alpha*gamma*math.exp(-gamma*p)/r**2 + 32*P1*alpha*d0*gamma*r1*r2*math.exp(-gamma*p)/r**3 - 16*P1*alpha*d1*gamma*r2*math.exp(-gamma*p)/r**2 + 16*P1*alpha*gamma**2*q0*r1*r2*math.exp(-gamma*p)/r**2 + P1*q1 + 16*P2*alpha*d0*gamma*r1**2*math.exp(-gamma*p)/r**3 - 16*P2*alpha*d0*gamma*math.exp(-gamma*p)/r**3 - 16*P2*alpha*d1*gamma*r1*math.exp(-gamma*p)/r**2 + 8*P2*alpha*gamma**2*q0*r1**2*math.exp(-gamma*p)/r**2 - 8*P2*alpha*gamma**2*q0*math.exp(-gamma*p)/r**2 - 16*a1*alpha*gamma*r1*r2*math.exp(-gamma*p)/r**2 + a1*p1 - 16*alpha*d0*e2*gamma*r2*w*math.exp(-gamma*p)/r**2 - 2*d0*p1*r1/r**2 + 2*d1*p1/r + e2*q0*w + 2*q1*r1/r]

def ligaduras(alpha, gamma, w, r, r1, r2, P1, P2, p, p1, p2, e2, a0, a1, d0, d1, q0, q1):
    return [8*P1*alpha*d0*gamma*p1*r1*math.exp(-gamma*p)/r**2 + 4*P1*alpha*gamma*q0*r1**2*math.exp(-gamma*p)/r**2 - 4*P1*alpha*gamma*q0*math.exp(-gamma*p)/r**2 + 2*P1*d0/r - 8*alpha*d1*gamma*p1*r1*math.exp(-gamma*p)/r**2 + 4*alpha*gamma**2*p1*q0*r1**2*math.exp(-gamma*p)/r**2 - 4*alpha*gamma**2*p1*q0*math.exp(-gamma*p)/r**2 - 4*alpha*gamma*q1*r1**2*math.exp(-gamma*p)/r**2 + 4*alpha*gamma*q1*math.exp(-gamma*p)/r**2 - 2*d1/r - 1/2*p1*q0, -24*P1*alpha*d0*gamma*p1*r1**2*math.exp(-gamma*p)/r**3 + 8*P1*alpha*d0*gamma*p1*math.exp(-gamma*p)/r**3 + 24*P1*alpha*d1*gamma*p1*r1*math.exp(-gamma*p)/r**2 - 12*P1*alpha*gamma**2*p1*q0*r1**2*math.exp(-gamma*p)/r**2 + 4*P1*alpha*gamma**2*p1*q0*math.exp(-gamma*p)/r**2 + 12*P1*alpha*gamma*q1*r1**2*math.exp(-gamma*p)/r**2 - 4*P1*alpha*gamma*q1*math.exp(-gamma*p)/r**2 - 2*P1*d0*r1/r**2 + 2*P1*d1/r + 12*a1*alpha*gamma*p1*r1**2*math.exp(-gamma*p)/r**2 - 4*a1*alpha*gamma*p1*math.exp(-gamma*p)/r**2 + 2*a1*r1/r + 8*alpha*d0*e2*gamma*p1*r1*w*math.exp(-gamma*p)/r**2 + 4*alpha*e2*gamma*q0*r1**2*w*math.exp(-gamma*p)/r**2 - 4*alpha*e2*gamma*q0*w*math.exp(-gamma*p)/r**2 + 2*d0*e2*w/r - 2*d0*r1**2/r**3 + 2*d0/r**3 + 2*d1*r1/r**2 - 1/2*p1*q1]
